#include <asio.hpp>
#include <iostream>

int main() {
    asio::io_context io;
    asio::steady_timer timer(io, std::chrono::seconds(1));
    asio::ip::tcp::socket sock(io);

    timer.async_wait([](std::error_code ec) {
        if (!ec) std::cout << "1 segundo depois!\n";
    });

    io.run(); // Executa o loop de eventos até terminar
}

